}

[data-stage-theme="dark"] {
  --halo-surface: rgba(22, 23, 26, 0.7);
  --halo-surface-elevated: rgba(30, 32, 38, 0.85);
  --halo-surface-strong: rgba(38, 41, 48, 0.95);
  --halo-surface-recessed: rgba(0, 0, 0, 0.45);
  --halo-surface-tint: rgba(18, 19, 22, 0.6);

  --halo-edge: rgba(255, 255, 255, 0.14);
  --halo-edge-soft: rgba(255, 255, 255, 0.06);
  --halo-edge-bright: rgba(255, 255, 255, 0.28);
  --halo-edge-inner: inset 0 1px 1px 0 rgba(255, 255, 255, 0.2), inset 0 -1px 1px 0 rgba(0, 0, 0, 0.6);
  --halo-edge-outer: 0 0 0 1px rgba(255, 255, 255, 0.08);

  --halo-highlight: linear-gradient(135deg, rgba(255, 255, 255, 0.22) 0%, rgba(255, 255, 255, 0.04) 38%, rgba(255, 255, 255, 0) 100%);
  --halo-highlight-strength: 0.55;

  --halo-shadow-contact: 0 1px 2px -0.5px rgba(0, 0, 0, 0.4), 0 3px 6px 0 rgba(0, 0, 0, 0.3);
  --halo-shadow-elevated: 0 8px 24px -4px rgba(0, 0, 0, 0.65), 0 3px 8px -2px rgba(0, 0, 0, 0.4);
  --halo-shadow-ambient: 0 20px 48px -12px rgba(0, 0, 0, 0.85);
  --halo-shadow-compressed: 0 1px 2px 0 rgba(0, 0, 0, 0.6);

  --halo-refraction-strength: 0.18;
  --halo-noise-opacity: 0.035;
  --halo-glow: rgba(255, 255, 255, 0.04);

  --halo-focus-color: #38bdf8;
  --halo-focus-offset-color: #0c0d0f;
  --halo-focus-outer-color: rgba(56, 189, 248, 0.35);

